shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/tokio/tests/sync_broadcast.rs
+++ b/tokio/tests/sync_broadcast.rs
@@ -522,3 +522,46 @@ fn resubscribe_lagged() {
     assert_empty!(rx);
     assert_empty!(rx_resub);
 }
+
+#[test]
+fn resubscribe_closed_try_recv() {
+    let (tx, rx) = broadcast::channel::<u32>(4);
+    drop(tx);
+
+    let mut rx_resub = rx.resubscribe();
+    drop(rx);
+
+    assert_closed!(rx_resub.try_recv());
+}
+
+#[test]
+fn resubscribe_closed_recv() {
+    let (tx, rx) = broadcast::channel::<u32>(4);
+    drop(tx);
+
+    let mut rx_resub = rx.resubscribe();
+    drop(rx);
+
+    let err = assert_ready_err!(task::spawn(rx_resub.recv()).poll());
+    assert!(is_closed(err));
+}
+
+#[test]
+fn resubscribe_closed_with_unread_messages() {
+    let (tx, mut rx) = broadcast::channel(2);
+    assert_ok!(tx.send(1));
+    assert_ok!(tx.send(2));
+    drop(tx);
+
+    let mut rx_resub = rx.resubscribe();
+    let mut rx_resub_recv = rx_resub.resubscribe();
+    assert_closed!(rx_resub.try_recv());
+    let err = assert_ready_err!(task::spawn(rx_resub_recv.recv()).poll());
+    assert!(is_closed(err));
+
+    assert_eq!(assert_recv!(rx), 1);
+    assert_eq!(assert_recv!(rx), 2);
+    assert_closed!(rx.try_recv());
+}
PATCH
cargo test --offline --test sync_broadcast --features full resubscribe_closed

